content:
:root {
  font-family: Inter, system-ui, Avenir, Helvetica, Arial, sans-serif;
  line-height: 1.5;
  font-weight: 400;

  color-scheme: light dark;
  color: #213547;
  background-color: #f0f2f5;

  font-synthesis: none;
  text-rendering: optimizeLegibility;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  margin: 0;
  display: flex;
  place-items: center;
  min-width: 320px;
  min-height: 100vh;
  justify-content: center;
  align-items: center;
}

#root {
  width: 100%;
  max-width: 800px;
  margin: 0 auto;
  padding: 1rem;
  text-align: center;
}

.app-container {
  display: flex;
  flex-direction: column;
  gap: 1rem;
  background: #ffffff;
  padding: 1.5rem;
  border-radius: 16px;
  box-shadow: 0 4px 20px rgba(0, 0, 0, 0.08);
  width: 100%;
  max-width: 760px;
  margin: 0 auto;
}

.header {
  display: flex;
  flex-direction: column;
  gap: 1rem;
  align-items: center;
}

.title {
  font-size: 1.5rem;
  font-weight: 700;
  color: #1a1a1a;
}

.toolbar {
  display: flex;
  flex-wrap: wrap;
  gap: 1rem;
  justify-content: center;
  align-items: center;
  background: #f8fafc;
  padding: 0.75rem 1rem;
  border-radius: 12px;
  width: 100%;
  border: 1px solid #e2e8f0;
}

.tool-group {
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

.color-btn {
  width: 32px;
  height: 32px;
  border-radius: 50%;
  border: 2px solid #cbd5e1;
  cursor: pointer;
  transition: transform 0.2s, border-color 0.2s;
  padding: 0;
}

.color-btn:hover {
  transform: scale(1.1);
}

.color-btn.active {
  border-color: #0ea5e9;
  transform: scale(1.15);
  box-shadow: 0 0 0 2px rgba(14, 165, 233, 0.3);
}

.range-input {
  cursor: pointer;
  accent-color: #0ea5e9;
}

.btn {
  padding: 0.5rem 1rem;
  border-radius: 8px;
  border: 1px solid #cbd5e1;
  background-color: #ffffff;
  color: #334155;
  font-weight: 600;
  cursor: pointer;
  transition: background-color 0.2s, border-color 0.2s;
}

.btn:hover {
  background-color: #f1f5f9;
  border-color: #94a3b8;
}

.btn-clear {
  background-color: #fee2e2;
  border-color: #fca5a5;
  color: #dc2626;
}

.btn-clear:hover {
  background-color: #fecaca;
  border-color: #f87171;
}

.canvas-container {
  width: 100%;
  display: flex;
  justify-content: center;
  border: 2px dashed #cbd5e1;
  border-radius: 12px;
  overflow: hidden;
  background-color: #ffffff;
  touch-action: none;
}

.drawing-canvas {
  display: block;
  cursor: crosshair;
  background-color: #ffffff;
  width: 100%;
  max-width: 100%;
  height: auto;
  touch-action: none;
}

@media (max-width: 600px) {
  .app-container {
    padding: 0.75rem;
  }

  .toolbar {
    flex-direction: column;
    gap: 0.75rem;
  }
}

import { useRef, useState, useEffect, type PointerEvent } from 'react'

export default function App() {
  const canvasRef = useRef<HTMLCanvasElement | null>(null)
  const [isDrawing, setIsDrawing] = useState<boolean>(false)
  const [color, setColor] = useState<string>('#000000')
  const [lineWidth, setLineWidth] = useState<number>(5)
  const [isEraser, setIsEraser] = useState<boolean>(false)

  const colors = ['#000000', '#ef4444', '#3b82f6', '#10b981', '#f59e0b', '#8b5cf6', '#ffffff']

  useEffect(() => {
    const canvas = canvasRef.current
    if (!canvas) return
    const ctx = canvas.getContext('2d')
    if (!ctx) return

    // キャンバスの内部解像度を設定
    canvas.width = 700
    canvas.height = 450

    // 初期背景を白に設定
    ctx.fillStyle = '#ffffff'
    ctx.fillRect(0, 0, canvas.width, canvas.height)
    ctx.lineCap = 'round'
    ctx.lineJoin = 'round'
  }, [])

  const startDrawing = (e: PointerEvent<HTMLCanvasElement>) => {
    const canvas = canvasRef.current
    if (!canvas) return
    const ctx = canvas.getContext('2d')
    if (!ctx) return

    const rect = canvas.getBoundingClientRect()
    const scaleX = canvas.width / rect.width
    const scaleY = canvas.height / rect.height

    const x = (e.clientX - rect.left) * scaleX
    const y = (e.clientY - rect.top) * scaleY

    setIsDrawing(true)
    ctx.beginPath()
    ctx.moveTo(x, y)
  }

  const draw = (e: PointerEvent<HTMLCanvasElement>) => {
    if (!isDrawing) return
    const canvas = canvasRef.current
    if (!canvas) return
    const ctx = canvas.getContext('2d')
    if (!ctx) return

    const rect = canvas.getBoundingClientRect()
    const scaleX = canvas.width / rect.width
    const scaleY = canvas.height / rect.height

    const x = (e.clientX - rect.left) * scaleX
    const y = (e.clientY - rect.top) * scaleY

    ctx.strokeStyle = isEraser ? '#ffffff' : color
    ctx.lineWidth = lineWidth
    ctx.lineTo(x, y)
    ctx.stroke()
  }

  const stopDrawing = () => {
    setIsDrawing(false)
    const canvas = canvasRef.current
    if (!canvas) return
    const ctx = canvas.getContext('2d')
    if (ctx) {
      ctx.beginPath()
    }
  }

  const clearCanvas = () => {
    const canvas = canvasRef.current
    if (!canvas) return
    const ctx = canvas.getContext('2d')
    if (!ctx) return

    ctx.fillStyle = '#ffffff'
    ctx.fillRect(0, 0, canvas.width, canvas.height)
  }

  return (
    <div className="app-container">
      <header className="header">
        <h1 className="title">お絵かきボード</h1>
        <div className="toolbar">
          <div className="tool-group">
            {colors.map((c) => (
              <button
                key={c}
                className={`color-btn ${!isEraser && color === c ? 'active' : ''}`}
                style={{ backgroundColor: c }}
                onClick={() => {
                  setColor(c)
                  setIsEraser(false)
                }}
                aria-label={`色 ${c}`}
              />
            ))}
          </div>

          <div className="tool-group">
            <label htmlFor="line-width" style={{ fontSize: '0.875rem', fontWeight: 600 }}>太さ: {lineWidth}px</label>
            <input
              id="line-width"
              type="range"
              min="1"
              max="50"
              value={lineWidth}
              onChange={(e) => setLineWidth(Number(e.target.value))}
              className="range-input"
            />
          </div>

          <div className="tool-group">
            <button
              className={`btn ${isEraser ? 'active' : ''}`}
              onClick={() => setIsEraser(!isEraser)}
              style={isEraser ? { backgroundColor: '#e2e8f0', borderColor: '#cbd5e1' } : undefined}
            >
              {isEraser ? 'ペンモード' : '消しゴム'}
            </button>
            <button className="btn btn-clear" onClick={clearCanvas}>
              全消去
            </button>
          </div>
        </div>
      </header>

      <div className="canvas-container">
        <canvas
          ref={canvasRef}
          className="drawing-canvas"
          onPointerDown={startDrawing}
          onPointerMove={draw}
          onPointerUp={stopDrawing}
          onPointerLeave={stopDrawing}
        />
      </div>
    </div>
  )
}
